from collections import Counter

def runs_1d(vals, color):
    runs=[]; start=None
    for i,v in enumerate(vals+[None]):
        if v==color and start is None: start=i
        elif v!=color and start is not None:
            runs.append((start,i-1)); start=None
    return runs

def edge_run(grid, color, edge):
    h,w=len(grid),len(grid[0])
    vals={'top':grid[0], 'bottom':grid[-1], 'left':[r[0] for r in grid], 'right':[r[-1] for r in grid]}[edge]
    runs=runs_1d(vals,color)
    return max(runs,key=lambda r:r[1]-r[0]+1) if runs else None

def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
